-- ==============================================================================
-- EDUSPHERE AI — COMPLETE PUNE DIRECTORY & PRODUCTION DATA CLEANUP
-- 1. Purges all demo/placeholder colleges.
-- 2. Eliminates duplicates (e.g. legacy GCOEP in favor of COEP Technological University).
-- 3. Sets Annual Tuition to NULL (displayed as NA in UI).
-- 4. Upserts verified Pune colleges, programs, and cutoffs.
-- ==============================================================================

BEGIN;

-- 1. Purge all placeholder/demo college rows from public.colleges
DELETE FROM public.colleges 
WHERE data_source = 'demo_seed' 
   OR name LIKE 'Demo %'
   OR id IN (
     '29ddd3a0-9596-4468-8c35-5763d87702fc',
     'e35a5d08-b500-42d3-a31d-3b88eccc3c3c',
     '51b1116e-5829-4460-b9dd-93f5db2c36a3'
   );

-- 2. Cleanly reconcile duplicate legacy GCOEP entry
DELETE FROM public.colleges 
WHERE id = '00000000-0000-0000-0002-000000000002';

-- 3. Ensure required columns exist
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'colleges' AND column_name = 'primary_stream') THEN
        ALTER TABLE public.colleges ADD COLUMN primary_stream TEXT;
    END IF;

    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'colleges' AND column_name = 'naac_grade') THEN
        ALTER TABLE public.colleges ADD COLUMN naac_grade TEXT;
    END IF;

    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'colleges' AND column_name = 'official_website') THEN
        ALTER TABLE public.colleges ADD COLUMN official_website TEXT;
    END IF;

    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'colleges' AND column_name = 'provenance') THEN
        ALTER TABLE public.colleges ADD COLUMN provenance TEXT;
    END IF;

    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'colleges' AND column_name = 'data_source') THEN
        ALTER TABLE public.colleges ADD COLUMN data_source TEXT;
    END IF;
END $$;

-- 4. Create public.college_courses normalized table
CREATE TABLE IF NOT EXISTS public.college_courses (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    course_id INT UNIQUE NOT NULL,
    college_id UUID NOT NULL REFERENCES public.colleges(id) ON DELETE CASCADE,
    source_college_id INT,
    stream TEXT NOT NULL,
    course_name TEXT NOT NULL,
    intake INT DEFAULT 0,
    program_url TEXT,
    jee_cutoff TEXT,
    created_at TIMESTAMPTZ DEFAULT now(),
    updated_at TIMESTAMPTZ DEFAULT now(),
    CONSTRAINT uq_college_course_name UNIQUE(college_id, course_name)
);

DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'college_courses' AND column_name = 'program_url') THEN
        ALTER TABLE public.college_courses ADD COLUMN program_url TEXT;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'college_courses' AND column_name = 'jee_cutoff') THEN
        ALTER TABLE public.college_courses ADD COLUMN jee_cutoff TEXT;
    END IF;
END $$;

ALTER TABLE public.college_courses ENABLE ROW LEVEL SECURITY;

DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'college_courses' AND policyname = 'Allow public read access to college_courses') THEN
        CREATE POLICY "Allow public read access to college_courses" ON public.college_courses FOR SELECT USING (true);
    END IF;
END $$;

CREATE INDEX IF NOT EXISTS idx_college_courses_college_id ON public.college_courses(college_id);
CREATE INDEX IF NOT EXISTS idx_college_courses_course_name ON public.college_courses(course_name);
CREATE INDEX IF NOT EXISTS idx_college_courses_stream ON public.college_courses(stream);

-- 5. Create public.college_cutoffs normalized table
CREATE TABLE IF NOT EXISTS public.college_cutoffs (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    course_id INT NOT NULL REFERENCES public.college_courses(course_id) ON DELETE CASCADE,
    college_id UUID NOT NULL REFERENCES public.colleges(id) ON DELETE CASCADE,
    exam TEXT NOT NULL,
    cutoff_open NUMERIC(5,2),
    cutoff_obc NUMERIC(5,2),
    cutoff_sc NUMERIC(5,2),
    cutoff_st NUMERIC(5,2),
    quota TEXT DEFAULT 'General',
    year INT DEFAULT 2024,
    created_at TIMESTAMPTZ DEFAULT now(),
    updated_at TIMESTAMPTZ DEFAULT now(),
    CONSTRAINT uq_course_exam UNIQUE(course_id, exam)
);

ALTER TABLE public.college_cutoffs ENABLE ROW LEVEL SECURITY;

DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'college_cutoffs' AND policyname = 'Allow public read access to college_cutoffs') THEN
        CREATE POLICY "Allow public read access to college_cutoffs" ON public.college_cutoffs FOR SELECT USING (true);
    END IF;
END $$;

CREATE INDEX IF NOT EXISTS idx_college_cutoffs_course_id ON public.college_cutoffs(course_id);
CREATE INDEX IF NOT EXISTS idx_college_cutoffs_college_id ON public.college_cutoffs(college_id);
CREATE INDEX IF NOT EXISTS idx_college_cutoffs_exam ON public.college_cutoffs(exam);

